#include <iostream>
#include <string>

int main() {
    std::string inp;
    std::getline(std::cin, inp);
    char head = inp[0];
    std::string tail = inp.substr(1);
    size_t pos;
    while ((pos = tail.find("dot")) != std::string::npos) {
        tail.replace(pos, 3, ".");
    }
    std::string combined_str(1, head);
    combined_str += tail;
    if (combined_str.size() > 0 && combined_str.back() == '.') {
        combined_str.back() = 't'; // temporarily replace '.' with 't'
        combined_str += "dot"; // append 'dot' to the end
        combined_str.pop_back(); // remove the 't' replaced earlier
    }
    char head_char = combined_str[0];
    std::string tail_part = combined_str.substr(1);
    size_t at_pos = tail_part.find("at");
    if (at_pos != std::string::npos) {
        tail_part.replace(at_pos, 2, "@");
    }
    if (!tail_part.empty() && tail_part.back() == '@') {
        tail_part.back() = 't'; // temporarily replace '@' with 't'
        tail_part += "at"; // append 'at'
        tail_part.back() = '@'; // restore '@'
    }
    std::cout << head_char << tail_part << std::endl;
    return 0;
}
